static inline int W3DTreeAliasCaseCmp(const char* a, const char* b)
{
    while (*a && *b) {
        unsigned char ca = (unsigned char)*a;
        unsigned char cb = (unsigned char)*b;
        if (ca >= 'A' && ca <= 'Z') ca = (unsigned char)(ca + 32);
        if (cb >= 'A' && cb <= 'Z') cb = (unsigned char)(cb + 32);
        if (ca != cb) return (int)ca - (int)cb;
        ++a; ++b;
    }
    return (int)(unsigned char)*a - (int)(unsigned char)*b;
}

static inline bool W3DTreeAliasEnabled()
{
    // GeneralsX @bugfix Qoder 21/10/2026: T10 new-tree alias is temporarily OFF by default,
    // restoring the original retail trees on every path (tree buffer and W3DModelDraw).
    // GENERALSX_TREE_OVERRIDE=1 brings the new GX*_rts trees back for A/B.
    static int s_enabled = -1;
    if (s_enabled < 0) {
        const char* e = getenv("GENERALSX_TREE_OVERRIDE");
        s_enabled = (e != nullptr && *e != 0 && atoi(e) != 0) ? 1 : 0;
    }
    return s_enabled != 0;
}

static inline const char* W3DTreeAliasResolve(const char* name)
{
    if (!name) return name;
    if (!W3DTreeAliasEnabled()) return name;
    for (unsigned i = 0; i < sizeof(kW3DTreeAliasTable) / sizeof(kW3DTreeAliasTable[0]); ++i) {
        if (W3DTreeAliasCaseCmp(name, kW3DTreeAliasTable[i].from) == 0)
            return kW3DTreeAliasTable[i].to;
    }
    return name;
}

static inline const char* W3DTreeAliasResolveModelTexture(const char* model)
{
    if (!model) return nullptr;
    if (!W3DTreeAliasEnabled()) return nullptr;
    for (unsigned i = 0; i < sizeof(kW3DTreeModelTextureTable) / sizeof(kW3DTreeModelTextureTable[0]); ++i) {
        if (W3DTreeAliasCaseCmp(model, kW3DTreeModelTextureTable[i].model) == 0)
            return kW3DTreeModelTextureTable[i].texture;
    }
    return nullptr;
}
